code.python:
class Solution:
    def squareFloor(self, x: int) -> int:
        lo, hi = 0, min(x, 10**8)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid * mid <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo

code.java:
class Solution {
    public long squareFloor(long x) {
        long lo = 0, hi = Math.min(x, 100_000_000L);
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            if (mid * mid <= x) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}

