long long squareFloor(long long x) {
    long long lo = 0, hi = x < 100000000LL ? x : 100000000LL;
    while (lo < hi) {
        long long mid = lo + (hi - lo + 1) / 2;
        if (mid * mid <= x) lo = mid;
        else hi = mid - 1;
